private fun createPlayer(settings: PlayerSettings, overrides: ApiOverrides = ApiOverrides(), analytics: ApiAnalyticsSettings = apiAnalyticsSettings, callbacks: ApiCallbackContext = apiCallbacks): Player {
    val prepared = ApiNativeFactories.player(context, overrides.player(settings.toPlayerConfig(licenseKey), callbacks), overrides.values)
    val result = playerFactory?.invoke(prepared.config) ?: Player(context, prepared.config, analytics.playerConfig(analyticsLicenseKey, callbacks))
    preparedCompanions = prepared.hosts
    return result
}

fun toPlayerConfig(licenseKey: String) = PlayerConfig(
    key = licenseKey,
    playbackConfig = PlaybackConfig(
        isAutoplayEnabled = autoplay, isMuted = muted, isTimeShiftEnabled = timeShift,
        preferredAudioLanguages = preferredAudioLanguages.toList(),
    ),
    bufferConfig = BufferConfig(
        audioAndVideo = BufferMediaTypeConfig(forwardDuration),
        startupThreshold = startupThreshold, restartThreshold = restartThreshold,
    ),
    adaptationConfig = AdaptationConfig(
        maxSelectableVideoBitrate = maxVideoBitrate, preload = preload,
        isRebufferingAllowed = rebuffering, qualityStabilityBalance = qualityStabilityBalance,
    ),
    networkConfig = NetworkConfig(
        retryHttpRequestConfig = httpRetryDelays?.let { RetryHttpRequestConfig.Retry(it.toList()) }
            ?: RetryHttpRequestConfig.LinearIncreasingBackoffRetry,
    ),
)

fun toSourceConfig(): SourceConfig {
    val config = if (!useLegacyMediaSource) SourceConfig(url, type) else when (type) {
        SourceType.Hls -> SourceConfig(com.bitmovin.player.api.source.HLSSource(url))
        SourceType.Dash -> SourceConfig(com.bitmovin.player.api.source.DASHSource(url))
        SourceType.Smooth -> SourceConfig(com.bitmovin.player.api.source.SmoothSource(url))
        SourceType.Progressive -> SourceConfig(com.bitmovin.player.api.source.ProgressiveSource(url))
    }
    return config.apply {
        title = this@SourceSettings.title.ifBlank { null }
        posterSource = posterUrl.ifBlank { null }; isPosterPersistent = posterPersistent
        options = SourceOptions(startOffset, offsetReference)
        liveConfig = liveTargetLatency?.let { SourceLiveConfig(targetLatency = it) }
        preferredAudioLanguages = this@SourceSettings.preferredAudioLanguages.toList()
        subtitleTracks = externalSubtitle?.let { listOf(it.toSubtitleTrack()) } ?: emptyList()
    }
}

val sourceConfigs = configs ?: sourceConfigurations(callbacks = callbacks)
val sources = sourceConfigs.map { sourceConfig -> sourceFactory?.invoke(sourceConfig)
    ?: Source(sourceConfig, com.bitmovin.player.api.analytics.AnalyticsSourceConfig.Enabled(apiAnalyticsSettings.sourceMetadata()), mediaSessionConfig = apiOverrides.mediaSession()) }

if (offlinePlayback == null && ApiCollectionSettings.PLAYLIST in apiOverrides.values)
    owner.load(com.bitmovin.player.api.playlist.PlaylistConfig(sources, apiOverrides.playlistOptions()))
else owner.load(sources.single())

internal fun playerViewConfig(mode: UiMode): PlayerViewConfig =
    if (mode.factoryFunction == null) {
        PlayerViewConfig()
    } else {
        PlayerViewConfig(
            uiConfig = UiConfig.WebUi(
                jsLocation = "file:///android_asset/bitmovinplayer-ui.js",
                cssLocation = "file:///android_asset/bitmovinplayer-ui.css",
                variant = UiConfig.WebUi.Variant.Custom(mode.factoryFunction),
            ),
        )
    }

private fun PlayerPreview(controller: PlayerController, uiMode: UiMode, modifier: Modifier) {
    val displayedPlayer = controller.player
    val vrRenderer = controller.apiVrRenderer
    if (vrRenderer != null) key(vrRenderer) {
        AndroidView(factory = { vrRenderer }, onRelease = { it.close() }, modifier = modifier)
    } else key(displayedPlayer, uiMode, controller.apiViewRevision) {
        AndroidView(factory = { context ->
            PlayerTouchHost(context, controller.attachView(PlayerView(context, displayedPlayer,
                controller.apiOverrides.view(playerViewConfig(uiMode)))))
        }, onRelease = { host ->
            host.releaseTouchOwnership()
            controller.releaseView(host.content as PlayerView)
        }, modifier = modifier)
    }
}

private fun <E : Event> onPlayer(type: KClass<E>, action: (E) -> Unit) {
    val owner = player
    val generation = playerGeneration
    val guarded: (E) -> Unit = { if (!released && player === owner && generation == playerGeneration) action(it) }
    owner.on(type, guarded)
    playerSubscriptions += { owner.off(type, guarded) }
}

internal fun analyticsSourceMetadata(values: Map<String, String>): SourceMetadata {
    validateAnalyticsMetadata(values, analyticsSourceKeys)
    return SourceMetadata(
        title = values["title"], videoId = values["videoId"], cdnProvider = values["cdnProvider"],
        path = values["path"], isLive = values["isLive"]?.toBooleanStrict(),
        customData = analyticsCustomData(values.filterKeys { it in analyticsCustomKeys }),
    )
}
